package pl.mos.backoffice.runnercontroller.egress

import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import pl.mos.backoffice.runnercontroller.security.CanonicalJson

class EgressAclTest {

    @Test
    fun `single-job ACL uses the job rule as default (docker proxy needs no credentials)`() {
        val acl = EgressAcl.forSingleJob(AclService("job-1", "pool-a", listOf("bo.example.com", "*.gradle.org", "bo.example.com")))
        assertThat(EgressAcl.toYaml(acl)).isEqualTo(
            """
            # generated by back-office runner-controller; do not edit
            version: "v1"
            services:
              - name: "job-1"
                project: "pool-a"
                action: "enforce"
                allowed_domains:
                  - "bo.example.com"
                  - "*.gradle.org"
            default:
              name: "default"
              project: "pool-a"
              action: "enforce"
              allowed_domains:
                - "bo.example.com"
                - "*.gradle.org"

            """.trimIndent(),
        )
    }

    @Test
    fun `pool ACL has one enforce role per job and a deny-all default`() {
        val acl = EgressAcl.forPool("pool-a", listOf(AclService("b", "pool-a", listOf("x.org")), AclService("a", "pool-a", emptyList())))
        val yaml = EgressAcl.toYaml(acl)
        assertThat(yaml).contains("  - name: \"a\"\n    project: \"pool-a\"\n    action: \"enforce\"\n    allowed_domains: []")
        assertThat(yaml.indexOf("name: \"a\"")).isLessThan(yaml.indexOf("name: \"b\""))
        assertThat(yaml).endsWith("default:\n  name: \"default\"\n  project: \"pool-a\"\n  action: \"enforce\"\n  allowed_domains: []\n")
        assertThat(EgressAcl.toYaml(EgressAcl.forPool("p", emptyList()))).contains("services: []")
    }

    @Test
    fun `registry serves hashed credentials and summarises decisions`() {
        val registry = EgressRegistry("pool-a")
        val creds = registry.register("job-1", listOf("bo.example.com"))
        assertThat(creds.username).isEqualTo("job-1")
        assertThat(creds.password).hasSizeGreaterThan(20)
        val snapshot = registry.snapshot()
        @Suppress("UNCHECKED_CAST")
        val credentials = snapshot["credentials"] as Map<String, String>
        assertThat(credentials["job-1"]).isEqualTo(CanonicalJson.sha256Hex(creds.password.toByteArray()))
        assertThat(snapshot.toString()).doesNotContain(creds.password)
        val v1 = snapshot["version"]
        registry.register("job-2", listOf("x.org"))
        assertThat(registry.snapshot()["version"]).isNotEqualTo(v1)

        registry.record(
            listOf(
                EgressDecision("job-1", "bo.example.com:443", true, "host matched allowed domain in rule", "2026-09-28T10:00:00Z"),
                EgressDecision("job-1", "example.com:443", false, "rule has enforce policy", "2026-09-28T10:00:01Z"),
                EgressDecision("job-1", "example.com:443", false, "rule has enforce policy", "2026-09-28T10:00:02Z"),
                EgressDecision("unknown", "x:1", false, "", "t"),
            ),
        )
        registry.unregister("job-1")
        assertThat(registry.activeJobs()).containsExactly("job-2")
        val summary = registry.summary("job-1")
        assertThat(summary.decisions).isEqualTo(3)
        assertThat(summary.denied).containsExactly("example.com")
        val lines = "2026-09-28T10:00:00Z|bo.example.com:443|ALLOW|host matched allowed domain in rule\n" +
            "2026-09-28T10:00:01Z|example.com:443|DENY|rule has enforce policy\n" +
            "2026-09-28T10:00:02Z|example.com:443|DENY|rule has enforce policy"
        assertThat(summary.digest).isEqualTo("sha256:" + CanonicalJson.sha256Hex(lines.toByteArray()))
        registry.forget("job-1")
        assertThat(registry.summary("job-1").digest).isNull()
    }

    @Test
    fun `endpoint token check`() {
        val token = EgressToken("s3cret")
        assertThat(token.matches("Bearer s3cret")).isTrue()
        assertThat(token.matches("Bearer nope")).isFalse()
        assertThat(token.matches(null)).isFalse()
        assertThat(EgressToken("").matches("Bearer ")).isFalse()
    }
}
